#include <stdlib.h>
#include <string.h>
#include <omp.h>

#define MR 6
#define NR 16
#define KCMAX 320
#define MC 96

typedef float v8 __attribute__((vector_size(32)));
typedef float v8u __attribute__((vector_size(32), aligned(4)));

/* A is read directly from row-major storage (no packing); B is packed. */
static inline void kernel(int kc, const float *restrict a, int lda,
                          const float *restrict b, float *restrict C, int ldc,
                          int mr, int nr, int first)
{
    const float *a0 = a;
    const float *a1 = a + (size_t)(1 < mr ? 1 : mr - 1) * lda;
    const float *a2 = a + (size_t)(2 < mr ? 2 : mr - 1) * lda;
    const float *a3 = a + (size_t)(3 < mr ? 3 : mr - 1) * lda;
    const float *a4 = a + (size_t)(4 < mr ? 4 : mr - 1) * lda;
    const float *a5 = a + (size_t)(5 < mr ? 5 : mr - 1) * lda;

    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        v8 b0 = *(const v8 *)(b);
        v8 b1 = *(const v8 *)(b + 8);
        float x;
        x = a0[k]; c00 += x * b0; c01 += x * b1;
        x = a1[k]; c10 += x * b0; c11 += x * b1;
        x = a2[k]; c20 += x * b0; c21 += x * b1;
        x = a3[k]; c30 += x * b0; c31 += x * b1;
        x = a4[k]; c40 += x * b0; c41 += x * b1;
        x = a5[k]; c50 += x * b0; c51 += x * b1;
        b += NR;
    }

    if (mr == MR && nr == NR) {
#define ST(r, x0, x1) do { \
            v8u *p0 = (v8u *)(C + (size_t)(r) * ldc); \
            v8u *p1 = (v8u *)(C + (size_t)(r) * ldc + 8); \
            if (first) { *p0 = x0; *p1 = x1; } \
            else { *p0 += x0; *p1 += x1; } \
        } while (0)
        ST(0, c00, c01); ST(1, c10, c11); ST(2, c20, c21);
        ST(3, c30, c31); ST(4, c40, c41); ST(5, c50, c51);
#undef ST
    } else {
        v8 t[MR][2] __attribute__((aligned(32)));
        t[0][0] = c00; t[0][1] = c01; t[1][0] = c10; t[1][1] = c11;
        t[2][0] = c20; t[2][1] = c21; t[3][0] = c30; t[3][1] = c31;
        t[4][0] = c40; t[4][1] = c41; t[5][0] = c50; t[5][1] = c51;
        const float *tf = (const float *)t;
        for (int i = 0; i < mr; i++) {
            float *cr = C + (size_t)i * ldc;
            const float *tr = tf + i * NR;
            if (first)
                for (int j = 0; j < nr; j++) cr[j] = tr[j];
            else
                for (int j = 0; j < nr; j++) cr[j] += tr[j];
        }
    }
}

static float *gB;
static size_t capB;

static float *grow(float **p, size_t *cap, size_t nfloats)
{
    size_t bytes = (nfloats * sizeof(float) + 63) & ~(size_t)63;
    if (bytes > *cap) {
        free(*p);
        *p = (float *)aligned_alloc(64, bytes);
        *cap = bytes;
    }
    return *p;
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int nkb = (n + KCMAX - 1) / KCMAX;
    int kcb = (n + nkb - 1) / nkb;
    kcb = (kcb + 7) & ~7;
    nkb = (n + kcb - 1) / kcb;

    int npB = (n + NR - 1) / NR;
    float *Bp = grow(&gB, &capB, (size_t)npB * NR * n);

    int nth = omp_get_max_threads();
    int nib = (n + MC - 1) / MC;
    int njb = (4 * nth + nib - 1) / nib;
    if (njb < 1) njb = 1;
    int ppc = (npB + njb - 1) / njb;
    if (ppc > 32) ppc = 32;
    if (ppc < 4) ppc = 4;
    if (ppc > npB) ppc = npB;
    njb = (npB + ppc - 1) / ppc;
    int ntasks = nib * njb;

    #pragma omp parallel
    {
        #pragma omp for collapse(2) schedule(static)
        for (int kb = 0; kb < nkb; kb++) {
            for (int jp = 0; jp < npB; jp++) {
                int p0 = kb * kcb;
                int kc = n - p0 < kcb ? n - p0 : kcb;
                int j0 = jp * NR;
                int nr = n - j0 < NR ? n - j0 : NR;
                float *dst = Bp + (size_t)p0 * npB * NR + (size_t)jp * kc * NR;
                for (int k = 0; k < kc; k++) {
                    const float *src = B + (size_t)(p0 + k) * n + j0;
                    float *d = dst + (size_t)k * NR;
                    if (nr == NR) {
                        memcpy(d, src, NR * sizeof(float));
                    } else {
                        int j = 0;
                        for (; j < nr; j++) d[j] = src[j];
                        for (; j < NR; j++) d[j] = 0.0f;
                    }
                }
            }
        }

        #pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < ntasks; t++) {
            int ib = t / njb, jb = t % njb;
            int i0 = ib * MC;
            int mc = n - i0 < MC ? n - i0 : MC;
            int jp0 = jb * ppc;
            int jp1 = jp0 + ppc < npB ? jp0 + ppc : npB;
            for (int kb = 0; kb < nkb; kb++) {
                int p0 = kb * kcb;
                int kc = n - p0 < kcb ? n - p0 : kcb;
                const float *bbase = Bp + (size_t)p0 * npB * NR;
                const float *abase = A + (size_t)i0 * n + p0;
                for (int jp = jp0; jp < jp1; jp++) {
                    int jj = jp * NR;
                    int nr = n - jj < NR ? n - jj : NR;
                    const float *bp = bbase + (size_t)jp * kc * NR;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int mr = mc - ir < MR ? mc - ir : MR;
                        kernel(kc, abase + (size_t)ir * n, n, bp,
                               C + (size_t)(i0 + ir) * n + jj, n,
                               mr, nr, kb == 0);
                    }
                }
            }
        }
    }
}
